head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > headerFilter]<br/>GridView 컴포넌트의 Header 에 HeaderFilter 기능을 활성화합니다.",
    "validation" : [
        "mergeCells 속성에 의해 Body Cell 이 병합된 경우 defaultShowHeaderFilter=false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 구조 케이스 selectbox 기본값 설정 (정적 select1 은 초기 selectedIndex 미적용 → onpageload setValue)
    con_structType.setValue("normal");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_structType : normal(정상, 병합없음) / mergeCells(mergeCells=bycol 로 col1 세로 병합)
    //  (headerFilter 는 동적 변경 불가 → con 변경 시 Target 재생성 버튼으로 재렌더)
    let vStruct = con_structType.getValue();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] headerFilter=true + defaultShowHeaderFilter=true 로 생성 (DataList 바인딩)\n[절차] con_structType 에서 normal 또는 mergeCells 선택 후 Target 재생성 -> headerFilter 동작 확인 버튼 클릭\n[확인] normal = 병합 없음 + 필터행 표시 / mergeCells = col1 이 세로로 병합(Body Cell td rowspan)됨."', '', 'label1');

    // dataList 생성 (4행, col1~col4) - HeaderFilter 는 DataList 바인딩 전제
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // mergeCells 케이스 : col1 에 세로로 인접한 동일 값(A,A,B,B)을 넣어 bycol 병합이 실제로 발생하도록 구성
    if (vStruct === 'mergeCells') {
        dlt_bind.setJSON([
            {"col1":"A", "col2":"col2_1", "col3":"col3_1", "col4":"col4_1"},
            {"col1":"A", "col2":"col2_2", "col3":"col3_2", "col4":"col4_2"},
            {"col1":"B", "col2":"col2_3", "col3":"col3_3", "col4":"col4_3"},
            {"col1":"B", "col2":"col2_4", "col3":"col3_4", "col4":"col4_4"}
        ], false);
    }

    // 구조 케이스별 headerFilter gridView 생성
    await scwin.createHeaderFilterGridView(vStruct);
}



// HeaderFilter 필터 행(filterColumn)을 포함한 gridView 를 구조 케이스별로 동적 생성
scwin.createHeaderFilterGridView = async function (vStruct) {
    let grp_comp = $c.gcm.getTestGroup('');
    let ns = $c.gcm.strNameSpace;

    // 공통 : headerFilter="true" + defaultShowHeaderFilter="true" (정상이면 필터행 표시되어야 함)
    let hfAttr = ' headerFilter="true" defaultShowHeaderFilter="true"';
    // mergeCells 케이스만 mergeCells="bycol" (병합 모드 키워드) 부여 -> col1 세로 병합
    let mcAttr = (vStruct === 'mergeCells') ? ' mergeCells="bycol"' : '';

    let s = '';
    s += '<w2:gridView ' + ns + hfAttr + mcAttr + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="headerFilter 구조 케이스 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    // HeaderFilter 필터 행 (filterColumn)
    s += '<w2:row style="" id="rowFilter">';
    s += '<w2:filterColumn width="130" style="" id="filterColumn1" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="130" style="" id="filterColumn2" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="130" style="" id="filterColumn3" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="*" style="" id="filterColumn4" value=""></w2:filterColumn>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// headerFilter 동작 확인 : Body Cell 병합(td rowspan) 여부 + HeaderFilter 필터행 표시 여부 + _unsupportedHeaderFilter
scwin.btn_checkHeaderFilter_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");

    // Body Cell 병합 여부 (mergeCells=bycol 로 col1 이 세로 병합되면 td[rowspan] 생성)
    let bodyTable = document.querySelector("[id*='target1_body_table']");
    let spanTd = bodyTable ? bodyTable.querySelector("td[rowspan]:not([rowspan='1']), td[colspan]:not([colspan='1'])") : null;
    let merged = !!spanTd;

    // HeaderFilter 필터 행 표시 여부
    let filterTr = document.querySelector("[id*='target1_head_table'] tr.w2grid_header_filter");
    let shown = !!(filterTr && filterTr.style.display !== 'none');

    // 엔진 판정 : 미지원 구조 여부 (현 엔진 미탑재 시 undefined)
    let unsupported = target1._unsupportedHeaderFilter;

    scb.setReturnValue("Body Cell 병합(td rowspan) : " + (merged ? '있음' : '없음') + " / HeaderFilter 필터행 : " + (shown ? '표시' : '미표시') + " / _unsupportedHeaderFilter : " + unsupported);
}
